<div class="rounded-2xl bg-white p-5 shadow-sm ring-1 ring-slate-200"><div class="flex flex-col justify-between gap-4 border-b border-slate-100 pb-5 sm:flex-row sm:items-end"><div><h2 class="text-2xl font-black text-slate-900">Attendance log</h2><p class="mt-1 text-slate-500">Records refresh automatically every few seconds.</p></div><a id="export-link" href="export-attendance.php?date=<?= date('Y-m-d') ?>&section=all" class="rounded-xl border border-slate-300 px-4 py-3 text-center text-sm font-bold text-slate-700 hover:bg-slate-50">Export CSV</a></div><div class="mt-5 grid gap-4 sm:grid-cols-2"><label class="text-sm font-bold text-slate-700">Section<select id="sectionFilter" class="mt-2 w-full rounded-xl border border-slate-300 bg-white px-4 py-3"><option value="all">All sections</option><option>BSIT-4A</option><option>BSIT-4B</option><option>BSCS-4A</option><option>BSCS-4B</option></select></label><label class="text-sm font-bold text-slate-700">Date<input id="dateFilter" type="date" value="<?= date('Y-m-d') ?>" class="mt-2 w-full rounded-xl border border-slate-300 px-4 py-3"></label></div><div class="mt-6 overflow-x-auto"><table class="min-w-full text-left text-sm"><thead class="border-b border-slate-200 text-xs uppercase tracking-wider text-slate-500"><tr><th class="px-4 py-3">Student ID</th><th class="px-4 py-3">Name</th><th class="px-4 py-3">Section</th><th class="px-4 py-3">Date</th><th class="px-4 py-3">Time in</th><th class="px-4 py-3">Status</th></tr></thead><tbody id="attendance-rows" class="divide-y divide-slate-100"></tbody></table></div></div><script>const section=document.getElementById('sectionFilter'),date=document.getElementById('dateFilter'),rows=document.getElementById('attendance-rows'),exportLink=document.getElementById('export-link');function update(){const p=new URLSearchParams({section:section.value,date:date.value});rows.innerHTML='<tr><td colspan="6" class="px-4 py-8 text-center text-slate-500">Loading records…</td></tr>';fetch('get-latest-attendance.php?'+p).then(r=>r.text()).then(x=>rows.innerHTML=x).catch(()=>rows.innerHTML='<tr><td colspan="6" class="px-4 py-8 text-center text-rose-600">Could not load records.</td></tr>');exportLink.href='export-attendance.php?'+p}section.onchange=date.onchange=update;update();setInterval(update,10000)</script><?php adminFoot(); ?>
